INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 1, '{"stem": "学校组织一至三年级的学生去看儿童剧。三年级有207人，二年级有185人，一年级有133人。（1）三个年级一共去了多少人？", "options": null}', '525人', '207+185+133=525（人），三个年级一共去了 525 人。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.4"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "学校组织一至三年级共525名学生去看儿童剧。影剧院一楼有292个座位，二楼有215个座位。若三个年级的学生一起观看儿童剧，还缺多少个座位？（用两种方法计算）", "options": null}', '还缺18个。方法一：525−292−215=18（个）；方法二：525−(292+215)=18（个）', '方法一：总人数依次减去一楼、二楼座位数；方法二：先算总座位数 292+215=507（个），再用总人数减：525−507=18（个）。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.4"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "下表是星光小学一至三年级学生参与口腔检查的人数记录：一年级146人、二年级208人、三年级人数被弄脏看不清。卫生室统计出一至三年级参与口腔检查的总人数正好是600人。三年级参与口腔检查的有多少人？", "options": null}', '246人', '600−(146+208)=600−354=246（人）。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.4"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "星光小学三年级有246人参与口腔检查。四、五年级参与口腔检查的总人数比三年级的人数多158人，其中检查情况良好的有382人。四、五年级牙齿状况不良的有多少人？", "options": null}', '22人', '四五年级总人数：246+158=404（人）；不良人数：404−382=22（人）。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.4"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "欢欢外婆带了100元去超市，买一瓶洗衣液（每瓶52元）和一瓶洗发水（每瓶34元）。（1）还剩多少钱？（用两种方法计算）", "options": null}', '还剩14元。方法一：100−52−34=14（元）；方法二：100−(52+34)=14（元）', '方法一：100 元依次减去两种商品价钱；方法二：先算两种商品共 52+34=86（元），100−86=14（元）。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.4"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "欢欢外婆买完洗衣液和洗发水后还剩14元。她想用剩下的钱再买两支牙膏（每支8元），这些钱够吗？", "options": null}', '不够。2×8=16（元），16>14', '两支牙膏需要 8×2=16（元），比剩下的 14 元多 2 元，所以钱不够。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.4"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "王奶奶卖鸡蛋，上午卖出鸡蛋总数的一半多10个，下午又卖出剩下的一半多10个，最后剩下35个鸡蛋没卖出去。王奶奶原有多少个鸡蛋？", "options": null}', '200个', '倒推：下午卖出后剩35个，下午卖前有 (35+10)×2=90（个）；上午卖前（原有）有 (90+10)×2=200（个）。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.4"]', NULL, 0);
